import {language,format as f} from './i18n.js';
const link=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const card=(title,body)=>`<article class="source-item"><h3>${title}</h3>${body}</article>`;
export function renderEvidence({terrain,manifest}){
  const pt=language==='pt',optical=manifest?.layers?.optical;
  const terrainUrl='https://planetarymaps.usgs.gov/mosaic/mars2020_trn/CTX/ScienceInvestigationMaps_JPL/M20_JezeroCrater_CTXDEM_20m.tif';
  return `<p class="source-note">${pt?'O cenário humano é hipotético. As coordenadas de Rochette e o terreno são rastreáveis a fontes NASA/USGS. A rota é uma decisão do protótipo, não uma recomendação operacional da NASA.':'The human mission is hypothetical. Rochette coordinates and terrain are traceable to NASA/USGS sources. The route is a prototype decision, not a NASA operational recommendation.'}</p>`+
    card(pt?'1 / Terreno numérico que muda a rota':'1 / Numerical terrain that changes the route',`<p>${pt?'O DEM CTX de Jezero da USGS tem pixels de 20 m. O recorte foi reprojetado para a mesma origem local do mapa, amostrado por interpolação bilinear a cada 40 m; a declividade foi calculada por diferenças centrais de elevação em metros. Células desconhecidas e a borda de derivação são excluídas. Não usamos cores do MOLA como elevação.':'The USGS Jezero CTX DEM has 20 m source pixels. The subset was reprojected to the map’s local origin, sampled bilinearly on a 40 m grid, and slopes were derived from central elevation differences in metres. Unknown cells and the derivative perimeter are excluded. MOLA colors are not used as elevations.'}</p><p>${link(terrainUrl,pt?'GeoTIFF original USGS':'Original USGS GeoTIFF')} · ${link('https://astrogeology.usgs.gov/search/map/mars_2020_science_investigation_ctx_dem_mosaic',pt?'Descrição do produto':'Product description')} · ${link('assets/jezero-terrain.json',pt?'Grade local e metadados':'Local grid and metadata')}</p><p class="source-kicker">${terrain?`${f(terrain.validCells)} ${pt?'células conhecidas':'known cells'} · ${terrain.sourceResolutionMeters[0]} m → ${terrain.step} m`:pt?'Terreno não carregado':'Terrain not loaded'}</p><code>SHA-256: ${terrain?.sourceSha256??'—'}</code><p>${pt?'A precisão de alinhamento absoluto com o mosaico CTX não foi validada independentemente. A elevação mantém a referência vertical do produto distribuído; não é altura medida pelo rover.':'Absolute alignment with the CTX mosaic has not been independently validated. Elevation retains the distributed product’s vertical reference; it is not rover-measured local height.'}</p>`)+
    card(pt?'2 / Rochette: alvo e evidência científica':'2 / Rochette: target and scientific evidence',`<p>${pt?'A coordenada vem do waypoint NASA RMC 7_0, sol 180: 77,44436574° E, 18,43073940° N. A Tabela 2 de Simon et al. (2023) associa a coordenada arredondada a Rochette e às amostras Montdenier/Montagnac. É a posição de trabalho do rover, não o centro exato de um furo.':'The coordinate comes from NASA waypoint RMC 7_0, sol 180: 77.44436574° E, 18.43073940° N. Table 2 of Simon et al. (2023) associates the rounded coordinate with Rochette and the Montdenier/Montagnac samples. It is a rover workspace position, not an exact drill-hole center.'}</p><p>${link('assets/rochette-waypoint.geojson',pt?'Registro original preservado':'Preserved original record')} · ${link('https://mars.nasa.gov/mmgis-maps/M20/Layers/json/M20_waypoints.json','NASA GeoJSON')} · ${link('https://doi.org/10.1029/2022JE007474','Simon et al. (2023)')} · ${link('https://www.jpl.nasa.gov/news/nasas-perseverance-rover-collects-puzzle-pieces-of-mars-history/','NASA/JPL')}</p><p>${pt?'O habitat é hipotético, em 18,4407° N / 77,3971° E: uma área plana (menos de 4° num raio de 120 m), a oeste de um morro de cerca de 40 m que a linha reta até Rochette atravessa. O local foi escolhido para que o percurso tenha um obstáculo real do terreno; 18,4663° N / 77,4298° E é apenas a origem da projeção do mapa. A missão propõe documentar textura e contexto mineral de basalto alterado por água. Não implica uma missão humana existente nem evidência de vida.':'The habitat is hypothetical at 18.4407° N / 77.3971° E: a flat area (under 4° within 120 m) west of a ~40 m hill that the straight line to Rochette crosses. It was chosen so the walk faces a real terrain obstacle; 18.4663° N / 77.4298° E is only the map projection origin. The mission proposes documenting textures and mineral context in water-altered basalt. It implies neither an existing human mission nor evidence of life.'}</p>`)+
    card(pt?'3 / Método de planejamento e hipóteses':'3 / Planning method and assumptions',`<p>${pt?'A* em grade de 40 m, com vizinhança de oito células, exclui terreno sem dados ou acima do limite escolhido. O custo relativo pondera distância e declividade: distância × [1 + 4 × (declividade/limite)²]. O peso 4 e o limite padrão de 12° são hipóteses ajustáveis do protótipo, não valores de segurança da NASA. A simplificação mantém a transitabilidade e verifica o custo do segmento.':'A* on a 40 m grid with eight-cell connectivity excludes unknown terrain and cells above the selected slope limit. Relative cost weights distance and slope: distance × [1 + 4 × (slope/limit)²]. The weight of 4 and default 12° limit are prototype assumptions, not NASA safety values. Path simplification preserves passability and checks segment cost.'}</p><p>${pt?'A análise amostra cada segmento com espaçamento máximo de 10 m para consultar as células de 40 m; isso não aumenta a resolução dos dados. A referência direta é uma comparação, não uma recomendação automaticamente transitável. O retorno percorre o caminho inverso, e o perfil mostra apenas a ida.':'Analysis samples each segment at intervals no larger than 10 m to inspect the 40 m cells; this does not increase data resolution. The direct baseline is a comparison, not an automatically traversable recommendation. Return follows the reverse path; the elevation profile shows the outbound leg.'}</p><p>${pt?'O orçamento de tempo usa velocidade constante e trabalho científico informado pelo usuário. Os cenários variam velocidade e duração do trabalho; não são intervalos estatísticos, modelo fisiológico ou previsão de oxigênio.':'The time budget uses constant user-specified pace and science-work time. Scenarios vary pace and work duration; they are not statistical intervals, a physiological model, or an oxygen forecast.'}</p><p>${pt?'<strong>Regra de retorno (walkback):</strong> a ida usa o ritmo planejado; a volta é planejada como se o ritmo caísse para 75%. O horário-limite para deixar Rochette é: tempo de EVA − reserva − volta lenta. Se o alvo estiver além da distância em que ida + volta lenta já consomem o tempo disponível, o mapa marca o limite de retorno na rota. Inspirada nos limites de retorno a pé usados para planejar as travessias com o rover lunar da Apollo; não é uma regra operacional da NASA para Marte.':'<strong>Walkback rule:</strong> the outbound leg uses the planned pace; the return is planned as if pace drops to 75%. The latest time to leave Rochette is: EVA time − reserve − slow return. If the target lies beyond the distance at which outbound plus slow return already uses the available time, the map marks the walkback limit on the route. Inspired by the walkback limits used to plan Apollo lunar rover traverses; it is not a NASA operational rule for Mars.'}</p>`)+
    card(pt?'4 / Imagens de superfície do Perseverance':'4 / Perseverance surface images',`<p>${pt?'Três imagens brutas (Hazcam frontal, Navcam e SHERLOC WATSON) feitas nos sols 180–182 no site 7, drive 0, a mesma posição do waypoint 7_0. Mostram como é o local de trabalho; não participam do cálculo da rota. Não são calibradas e mostram 2021, não condições atuais.':'Three raw images (front Hazcam, Navcam and SHERLOC WATSON) taken on sols 180–182 at site 7, drive 0, the same position as waypoint 7_0. They show what the workspace looks like; they do not drive the route calculation. They are uncalibrated and show 2021, not current conditions.'}</p><p>${link('assets/surface/surface-images.json',pt?'IDs, datas, créditos e hashes':'IDs, dates, credits and hashes')} · ${link('https://mars.nasa.gov/mars2020/multimedia/raw-images/',pt?'Imagens brutas NASA Mars 2020':'NASA Mars 2020 raw images')}</p>`)+
    card(pt?'5 / Camadas de dados e funções':'5 / Data layers and their roles',`<p><strong>CTX:</strong> ${pt?'mosaico local NASA Mars 2020 / Caltech, produto nominal de 5 m/pixel; os tiles de visualização têm aproximadamente 10 m/pixel. Dá contexto visual, sem detecção automática de pedras.':'NASA Mars 2020 / Caltech local mosaic, nominal 5 m/pixel source; displayed tiles are approximately 10 m/pixel. It provides visual context without automatic boulder detection.'} ${link('https://murray-lab.caltech.edu/Mars2020/index.html','Caltech')} · ${optical?.tiles?.length??0} tiles.</p><p><strong>MOLA:</strong> ${pt?'relevo regional colorido, produto de 463 m/pixel. Apenas contexto; não participa do custo da rota.':'regional color hillshade, nominal 463 m/pixel product. Context only; it does not drive route cost.'}</p><p><strong>THEMIS Night IR:</strong> ${pt?'mosaico controlado de infravermelho noturno (100 m/pixel) do Mars Trek, reamostrado para a grade de 40 m. À noite, rocha e material consolidado retêm calor e aparecem mais quentes; areia e poeira esfriam mais rápido. As células são divididas em quartis de brilho dentro do recorte (25% mais frias / 25% mais quentes). É brilho relativo, não temperatura nem inércia térmica calibradas, e não entra no custo da rota. Checagem de plausibilidade: a parcela de células quentes cresce com a declividade (19% abaixo de 3°, 47% acima de 12°), como esperado para encostas rochosas.':'controlled night-time infrared mosaic (100 m/pixel) from Mars Trek, resampled to the 40 m grid. At night, rock and consolidated material retain heat and appear warmer; sand and dust cool faster. Cells are split by brightness quartiles within the subset (coolest 25% / warmest 25%). This is relative brightness, not calibrated temperature or thermal inertia, and it is not used in route cost. Plausibility check: the share of warm cells rises with slope (19% below 3°, 47% above 12°), as expected for rocky slopes.'} ${link('assets/jezero-night-ir.json',pt?'Grade e metadados':'Grid and metadata')}</p><p><strong>Curiosity RAD:</strong> ${pt?'cerca de 0,67 mSv/dia de raios cósmicos galácticos medidos na superfície (cratera Gale, ago/2012 a jun/2013). Usado só para estimar a ordem de grandeza da dose de uma EVA; não é um modelo de dosimetria para Jezero.':'about 0.67 mSv/day from galactic cosmic rays measured on the surface (Gale crater, Aug 2012 to Jun 2013). Used only to estimate the order of magnitude of one EVA’s dose; not a dosimetry model for Jezero.'} ${link('https://doi.org/10.1126/science.1244797','Hassler et al. (2014)')} · ${link('https://www.swri.org/newsroom/press-releases/swri-scientists-publish-first-radiation-measurements-the-surface-of-mars','SwRI')}</p><p>${link('https://trek.nasa.gov/mars/','NASA/JPL Mars Trek')} · ${link('assets/data-manifest.json',pt?'URLs e metadados de cada tile':'Per-tile URLs and metadata')}</p>`)+
    card(pt?'6 / Limites, validação e reprodução':'6 / Limits, validation, and reproduction',`<p>${pt?'Há testes de colisão com células bloqueadas, prevenção de atalhos diagonais, custo por declividade, dados desconhecidos, coordenadas, ida e volta, cenários de reserva, cobertura e zoom. A verificação de interface testa computador, celular, idiomas, exportação e ampliação do mapa. Isso não equivale a validação com astronautas ou a certificação operacional.':'Tests cover blocked cells, diagonal corner cutting, slope-dependent cost, unknown data, coordinates, round trips, reserve scenarios, coverage, and zoom. Browser checks cover desktop, mobile, languages, export, and expanded maps. This does not constitute astronaut validation or operational certification.'}</p><p>${pt?'O cenário de referência automatizado registra os parâmetros e resultados exatos desta versão. A avaliação humana continua sendo uma etapa aberta; nenhum resultado com usuários foi inventado.':'The automated reference scenario records this version’s exact parameters and outputs. Human usability evaluation remains an open step; no user-testing results have been fabricated.'}</p><p>${link('assets/validation-report.json',pt?'Cenário reproduzível':'Reproducible scenario')} · ${link('mission-brief.html',pt?'Resumo de missão em inglês':'English mission brief')}</p>`)+
    card('NASA Space Apps 2026',`<p>${link('https://www.spaceappschallenge.org/2026/challenges/interplanetary-survival-guide-martian-map/?tab=resources','Interplanetary Survival Guide: Martian Map')} · ${link('assets/challenge-resources.json',pt?'Recursos oficiais conferidos':'Verified challenge resources')}</p><p>${pt?'O Mars Trek é um recurso oficial do desafio e fornece as camadas MOLA/THEMIS. O DEM USGS e o mosaico CTX Caltech complementam esses recursos com terreno numérico e imagens locais.':'Mars Trek is an official challenge resource and supplies MOLA/THEMIS layers. The USGS DEM and Caltech CTX mosaic complement those resources with numerical terrain and local imagery.'}</p>`);
}
